import * as React from 'react';
import { cn } from '@/lib/utils';
import { resolveGap, type GapValue } from '../../utils/gap';

// Literal classes so Tailwind's scanner keeps them (runtime-built
// grid-cols-${n} would be purged — same rule as Grid).
const GRID_COLUMNS: Record<number, string> = {
  1: 'grid-cols-1',
  2: 'grid-cols-2',
  3: 'grid-cols-3',
  4: 'grid-cols-4',
};

export type FormLayoutProps = React.HTMLAttributes<HTMLElement> & {
  /** Grouping layout: even vertical stack (default), horizontal row, or responsive grid. */
  layout?: 'stack' | 'row' | 'grid';
  /** Grid column count (1-4); grid wraps naturally via responsive variants passed as className. */
  columns?: 1 | 2 | 3 | 4;
  /** Even spacing between children — token ('md') or exact pixels (16). */
  gap?: GapValue;
  /** Group label; renders a semantic <legend> when as="fieldset". */
  legend?: string;
  /** Supporting line under the legend (fieldset mode). */
  description?: string;
  /** Render as a semantic fieldset (default 'div'). */
  as?: 'div' | 'fieldset';
};

/**
 * Groups form fields with even, tokenized spacing — the layout half of
 * form composition (FormField/Fieldset provide the per-control semantics).
 * stack keeps one field per row, row flows fields inline, grid spreads
 * them across columns (1-4, literal classes so they survive purging).
 */
const FormLayout = React.forwardRef<HTMLElement, FormLayoutProps>(
  (
    {
      layout = 'stack',
      columns = 2,
      gap,
      legend,
      description,
      as = 'div',
      className,
      style,
      children,
      ...props
    },
    ref,
  ) => {
    const Tag = as as 'div' | 'fieldset';
    const gapResolved = resolveGap(gap ?? 'md');
    return (
      <Tag
        ref={ref as never}
        className={cn(
          'flex min-w-0',
          layout === 'stack' && 'flex-col',
          layout === 'row' && 'flex-row flex-wrap items-end',
          layout === 'grid' && `grid ${GRID_COLUMNS[columns]}`,
          gapResolved.className,
          className
        )}
        style={{ ...gapResolved.style, ...style }}
        {...props}
      >
        {legend && as === 'fieldset' && (
          <legend className="col-span-full p-0 text-sm font-medium leading-none">{legend}</legend>
        )}
        {description && as === 'fieldset' && (
          <p className="col-span-full text-xs text-muted-foreground">{description}</p>
        )}
        {children}
      </Tag>
    );
  }
);
FormLayout.displayName = 'FormLayout';

export { FormLayout };

{
  "id": "form-layout",
  "name": "FormLayout",
  "tier": "molecule",
  "description": "Groups form fields with even, tokenized spacing: vertical stack, horizontal row, or 1-4 column grid, optionally as a semantic fieldset.",
  "designIntent": "Field rhythm is the difference between a form that scans and one that doesn't. FormLayout owns the ARRANGEMENT (stack/row/grid + exact gap) while Fieldset owns the group semantics (legend) and FormField owns per-control wiring — three small pieces instead of one magic wrapper.",
  "props": [
    {
      "name": "layout",
      "type": "'stack' | 'row' | 'grid'",
      "defaultValue": "stack",
      "required": false,
      "description": "Grouping layout: even vertical stack, horizontal row, or column grid.",
      "enum": ["stack", "row", "grid"],
      "examples": ["grid", "row"]
    },
    {
      "name": "columns",
      "type": "1 | 2 | 3 | 4",
      "defaultValue": "2",
      "required": false,
      "description": "Grid column count (literal classes survive CSS purging).",
      "examples": ["2", "4"]
    },
    {
      "name": "gap",
      "type": "'none' | 'sm' | 'md' | 'lg' | 'xl' | number",
      "required": false,
      "description": "Even spacing between children — token or exact pixels (16).",
      "examples": ["lg", "16"]
    },
    {
      "name": "legend",
      "type": "string",
      "required": false,
      "description": "Group label rendered as a semantic <legend> (fieldset mode).",
      "examples": ["Billing details"]
    },
    {
      "name": "description",
      "type": "string",
      "required": false,
      "description": "Supporting line under the legend (fieldset mode)."
    },
    {
      "name": "as",
      "type": "'div' | 'fieldset'",
      "defaultValue": "div",
      "required": false,
      "description": "Render as a semantic fieldset when the layout names a group of controls.",
      "enum": ["div", "fieldset"],
      "examples": ["fieldset"]
    }
  ],
  "examples": [
    {
      "title": "Two-column settings grid",
      "code": "<FormLayout layout=\"grid\" columns={2} gap={16} as=\"fieldset\" legend=\"Profile\">\n  <FormField id=\"first\" label=\"First name\"><Input /></FormField>\n  <FormField id=\"last\" label=\"Last name\"><Input /></FormField>\n  <FormField id=\"email\" label=\"Email\"><Input type=\"email\" /></FormField>\n</FormLayout>",
      "description": "Exact 16px gaps; fields wrap into rows of two."
    },
    {
      "title": "Inline action row",
      "code": "<FormLayout layout=\"row\" gap=\"sm\">\n  <FormField id=\"q\" label=\"Search\"><Input type=\"search\" /></FormField>\n  <Button type=\"submit\">Go</Button>\n</FormLayout>"}
  ],
  "antiPatterns": [
    {
      "title": "Don't hand-roll spacer divs",
      "explanation": "Empty divs with heights drift from the token scale and break under different densities — gap exists for spacing.",
      "example": "<div className=\"h-4\" />  // avoid\n<FormLayout gap=\"md\">…</FormLayout>"
    },
    {
      "title": "Don't use fieldset mode without a legend",
      "explanation": "as=\"fieldset\" without legend renders an unnamed group — assistive tech announces nothing useful. Prefer div, or provide the legend.",
      "example": "<FormLayout as=\"fieldset\">…</FormLayout>  // nameless"
    }
  ],
  "accessibility": [
    {
      "feature": "Fieldset mode gives the group a name",
      "implementation": "legend renders as a real <legend>; use it whenever the layout wraps related controls",
      "userRequirements": "Legend text must name the choice, not the layout"
    },
    {
      "feature": "Reading order equals DOM order",
      "implementation": "Row/grid layouts reflow visually; source order never changes",
      "userRequirements": "Order fields by task flow, not visual position"
    }
  ],
  "compositionRules": [
    {
      "component": "FormField",
      "relationship": "FormLayout arranges the fields; each field keeps its own FormField wiring",
      "example": "<FormLayout layout=\"grid\" columns={2}><FormField …>…</FormField></FormLayout>"
    },
    {
      "component": "Form",
      "relationship": "Layouts live inside a Form (or standalone for filter bars)"
    },
    {
      "component": "Fieldset",
      "relationship": "Fieldset when the legend/grouping IS the point; FormLayout when spacing/arrangement is"
    }
  ],
  "relatedComponents": ["FormField", "Form", "Fieldset", "Grid"],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.1.0",
  "sourceDir": "form-layout",
  "exportName": "FormLayout"
}
